html:
{%- set cur = yht_currency(doc) -%}
<style>
.print-format { font-family: Arial, "Noto Sans", sans-serif; font-size: 9pt; color: #000; }
table.katc-doc { width: 100%; border-collapse: collapse; }
table.katc-doc > thead > tr > td { padding: 0; border: 0; }
/* The outer cell MUST be allowed to break. A table cell defaults to
   page-break-inside: avoid, which pushes the whole document onto one page and
   defeats the <thead> that repeats the letterhead. */
table.katc-doc > tbody > tr > td { padding: 0; border: 0; page-break-inside: auto !important; }
.katc-title { text-align: center; font-size: 14pt; font-weight: bold; letter-spacing: 1px; margin: 8px 0 0; }
.katc-title-ar { text-align: center; font-size: 12pt; font-weight: bold; direction: rtl; margin-bottom: 8px; }
.katc-meta { width: 100%; border-collapse: collapse; margin-bottom: 8px; }
.katc-meta td { border: 1px solid #999; padding: 3px 5px; font-size: 8.5pt; vertical-align: top; }
.katc-meta td.lbl { background: #f2f2f2; font-weight: bold; width: 18%; }
table.katc-items { width: 100%; border-collapse: collapse; margin-bottom: 8px; }
/* Repeats the column headers on every page. */
table.katc-items thead { display: table-header-group; }
table.katc-items th, table.katc-items td { border: 1px solid #999; padding: 3px 5px; font-size: 8.5pt; vertical-align: top; }
table.katc-items th { background: #f2f2f2; text-align: center; font-size: 8pt; }
table.katc-items td.num { text-align: right; }
table.katc-items td.ctr { text-align: center; }
.katc-ar { direction: rtl; text-align: right; }
.katc-totals { width: 55%; margin-left: auto; border-collapse: collapse; page-break-inside: avoid; }
.katc-totals td { border: 1px solid #999; padding: 3px 6px; font-size: 8.5pt; }
.katc-totals td.lbl { background: #f2f2f2; font-weight: bold; }
.katc-totals td.num { text-align: right; }
.katc-grand td { font-weight: bold; font-size: 9.5pt; }
.katc-words { font-size: 8.5pt; margin: 6px 0; text-align: center; }
.katc-terms { font-size: 8pt; color: #333; margin-top: 6px; }
.katc-sign { width: 100%; margin-top: 20px; border-collapse: collapse; page-break-inside: avoid; }
.katc-sign td { width: 50%; font-size: 8.5pt; vertical-align: top; padding: 4px 8px; }
.katc-rule { border-bottom: 1px solid #000; height: 13px; }
.katc-bank { font-size: 8.5pt; line-height: 1.45; page-break-inside: avoid; }
.katc-qr img { width: 26mm; height: 26mm; }
#footer-html { font-size: 8pt; text-align: center; color: #444; }
/* wkhtmltopdf is handed this as --footer-html, which is the ONLY way the page
   spans resolve. In the browser print view it would render inline instead. */
.print-format-gutter #footer-html { display: none; }
</style>
<table class="katc-doc">
  <thead><tr><td><div class="katc-spacer" style="height: {{ yht_katc_spacer_pt() }}pt"></div></td></tr></thead>
  <tbody><tr><td>
<div class="katc-title">QUOTATION</div>
<div class="katc-title-ar">عرض سعر</div>

<table class="katc-meta"><tbody>
  <tr>
    <td class="lbl">Quotation No / رقم عرض السعر</td><td>{{ doc.name }}</td>
    <td class="lbl">Date / التاريخ</td><td>{{ yht_date(doc.transaction_date) }}</td>
  </tr>
  <tr>
    <td class="lbl">Customer Name / اسم العميل</td><td>{{ doc.customer_name or doc.party_name or "" }}</td>
    <td class="lbl">Valid Till / صالح لغاية</td><td>{{ yht_date(doc.valid_till) }}</td>
  </tr>
</tbody></table>

<table class="katc-items">
  <thead><tr>
    <th style="width:6%">SN<div class="katc-ar">رقم</div></th>
    <th>ITEM NAME<div class="katc-ar">اسم العنصر</div></th>
    <th style="width:13%">QTY<div class="katc-ar">الكمية</div></th>
    <th style="width:16%">UNIT RATE<div class="katc-ar">سعر الوحدة</div></th>
    <th style="width:18%">AMOUNT<div class="katc-ar">المبلغ</div></th>
  </tr></thead>
  <tbody>
{%- for row in doc.items %}
    <tr>
      <td class="ctr">{{ loop.index }}</td>
      <td>{{ row.item_name or row.item_code or "" }}
{%- set ar = yht_item_ar(row) %}{% if ar %}<div class="katc-ar">{{ ar }}</div>{% endif %}</td>
      <td class="ctr">{{ row.qty }} {{ row.uom or row.stock_uom or "" }}</td>
      <td class="num">{{ yht_money(row.rate, cur) }}</td>
      <td class="num">{{ yht_money(row.amount, cur) }}</td>
    </tr>
{%- endfor %}
  </tbody>
</table>

<table class="katc-totals"><tbody>
  <tr><td class="lbl">Total - الإجمالي</td><td class="num">{{ yht_money(doc.total, cur) }}</td></tr>
  <tr><td class="lbl">Total Tax - إجمالي الضريبة</td><td class="num">{{ yht_money(doc.total_taxes_and_charges, cur) }}</td></tr>
  <tr class="katc-grand"><td class="lbl">Grand Total - الإجمالي النهائي</td><td class="num">{{ yht_money(doc.rounded_total or doc.grand_total, cur) }}</td></tr>
</tbody></table>

<div class="katc-words" style="text-align:left"><b>In Words:</b> {{ doc.in_words or "" }}</div>
<div class="katc-terms"><b>Terms and Conditions:</b><br>{{ doc.terms or "" }}</div>

{%- set creator = yht_creator_contact(doc) %}
<table class="katc-sign"><tbody><tr>
  <td>
{%- set bank = yht_bank_details() -%}
{#- Spec Step 10's VAT / bank block. The seller VAT is read in ordinary server-side
    Python for the same reason the bank details are — see print_helpers. -#}
{%- set seller_vat = yht_company_vat(doc) -%}
{%- if seller_vat or bank.iban or bank.account_no %}
<div class="katc-bank">
{%- if seller_vat %}
  VAT # <span dir="ltr">{{ seller_vat }}</span><br>
{%- endif %}
{%- if bank.iban or bank.account_no %}
  BANK DETAILS :<br>
  BANK NAME : {{ bank.bank }}<br>
  IBAN : <span dir="ltr">{{ bank.iban }}</span><br>
  A/C # <span dir="ltr">{{ bank.account_no }}</span>
{%- endif %}
</div>
{%- endif -%}
  </td>
  <td style="text-align:right">
    CONTACT : {{ yht_sales_person(doc) }}<br>
    Contact No: {{ creator.mobile }}<br>
    E-mail: {{ yht_katc_email() }}
  </td>
</tr></tbody></table>
  </td></tr></tbody>
</table>
<div id="footer-html">Page <span class="page"></span> of <span class="topage"></span></div>
